package metrics

import (
	"strings"
	"time"
)

func (mc *PrometheusMetricsClient) metricName(metric, kind, format string) string {
	if format != "v2" {
		name := sanitisePrometheusMetricName(metric)
		if kind == "timer" {
			name += "_timer"
		}
		return name
	}
	if def, ok := prometheusDefinitions[metric]; ok {
		return "smokescreen_" + def.name
	}
	name := sanitisePrometheusMetricName(metric)
	if kind == "counter" && !strings.HasSuffix(name, "_total") {
		name += "_total"
	}
	if kind == "timer" && !strings.HasSuffix(name, "_seconds") {
		name += "_seconds"
	}
	return "smokescreen_" + name
}

func (mc *PrometheusMetricsClient) metricHelp(metric, format string) string {
	if format != "v2" {
		return ""
	}
	if def, ok := prometheusDefinitions[metric]; ok {
		return def.help
	}
	return "Smokescreen " + metric + "."
}

func (mc *PrometheusMetricsClient) metricBuckets(metric, format string) []float64 {
	if format != "v2" {
		return nil
	}
	return prometheusDefinitions[metric].buckets
}

func (mc *PrometheusMetricsClient) timerValue(duration time.Duration, format string) float64 {
	if format == "v2" {
		return duration.Seconds()
	}
	return float64(duration.Milliseconds())
}

// emissionFormats selects collectors without changing the client's immutable format.
func (mc *PrometheusMetricsClient) emissionFormats() []string {
	if mc.format == "dual" {
		return []string{"legacy", "v2"}
	}
	return []string{mc.format}
}

package hostport

import (
	"fmt"
	"testing"

	"github.com/stretchr/testify/assert"
	"github.com/stretchr/testify/require"
)

func TestNew(t *testing.T) {
	for i, tt := range []struct {
		hostPort string
		host     string
		hostFQDN string
		port     int
		err      string
	}{
		{"127.0.0.1:1234", "127.0.0.1", "127.0.0.1", 1234, ""},
		{"example.net", "", "", NoPort, "missing port in address"},
		{"example.net:1337", "example.net", "example.net.", 1337, ""},
		{"example.net.:1337", "example.net.", "example.net.", 1337, ""},
		{"[example.net.]:1337", "example.net.", "example.net.", 1337, ""},
		{"[127.0.0.1]:1337", "127.0.0.1", "127.0.0.1", 1337, ""},
		{"[example.net]:1337", "example.net", "example.net.", 1337, ""},
		{"[[example.net]]:1337", "", "", NoPort, "missing port in address"},
		{"", "", "", NoPort, "missing port in address"},
		{":", "", "", NoPort, "invalid syntax"},
		{"::", "", "", NoPort, "too many colons in address"},
		{"2001:DB8::1337", "", "", NoPort, "too many colons in address"},
		{"[2001:DB8::1337]:1337", "2001:db8::1337", "2001:db8::1337", 1337, ""},
		{"[2001:DB8::1337]:91337", "2001:db8::1337", "2001:db8::1337", NoPort, "must be between 0 and 65535"},
		{"[2001:DB8::1337]:007", "2001:db8::1337", "2001:db8::1337", 7, ""},
		{"[2001:DB8::1337]:-12", "2001:db8::1337", "2001:db8::1337", NoPort, "must be between 0 and 65535"},
		{"[2001:DB8::1337]:https", "2001:db8::1337", "2001:db8::1337", NoPort, "invalid syntax"},
		{"🔐.example.com:123", "xn--jv8h.example.com", "xn--jv8h.example.com.", 123, ""},
		{"🔐.example.com:007", "xn--jv8h.example.com", "xn--jv8h.example.com.", 7, ""},
	} {
		t.Run(fmt.Sprintf("%d:%s", i+1, tt.hostPort), func(t *testing.T) {
			a := assert.New(t)
			hp, err := New(tt.hostPort, false)
			a.Equal(tt.host, hp.Host)
			a.Equal(tt.port, hp.Port)
			if tt.err != "" {
				a.ErrorContains(err, tt.err)
			} else {
				a.NoError(err)
			}
			// FQDN tests
			hp, err = New(tt.hostPort, true)
			a.Equal(tt.hostFQDN, hp.Host)
			a.Equal(tt.port, hp.Port)
			if tt.err == "" {
				a.NoError(err)
			} else {
				a.ErrorContains(err, tt.err)
			}
		})
	}
}

func TestNewWithScheme(t *testing.T) {
	var tests = []struct {
		scheme    string
		hostPort  string
		host      string
		port      int
		forceFQDN bool
		err       string
	}{
		{"http", "example.com", "example.com", 80, false, ""},
		{"http", "127.0.0.1", "127.0.0.1", 80, false, ""},
		{"https", "127.0.0.1:123", "127.0.0.1", 123, false, ""},
		{"https", "[2001:DB8::1337]", "[2001:db8::1337]", 443, false, "invalid domain \"[2001:DB8::1337]\": disallowed rune U+005B"},
		{"https", "2001:DB8::1337", "2001:db8::1337", 443, false, ""},
		{"https", "[2001:DB8::1337]:443", "2001:db8::1337", 443, false, ""},
		{"https", "[2001:db8::1337]:443", "2001:db8::1337", 443, false, ""},
		{"https", "[2001:DB8::1337]:-1", "2001:DB8::1337", NoPort, false, "invalid port number -1: must be between 0 and 65535"},
		{"https", "[2001:db8::1337]:111111", "2001:db8::1337", NoPort, false, "invalid port number 111111: must be between 0 and 65535"},
		{"unknown", "[[2001:DB8::1337]]", "[[2001:DB8::1337]]", NoPort, false, "unable to determine port for unknown"},
		{"https", "🔐.example.com:123", "xn--jv8h.example.com", 123, false, ""},
		{"smtp", "✉️.example.com.", "xn--4bi.example.com.", 25, false, ""},
		{"https", "🔐.example.com:123", "xn--jv8h.example.com.", 123, true, ""},
		{"https", "🔐.example.com:007", "xn--jv8h.example.com.", 7, true, ""},
		{"https", "foo_bar.example.com:007", "foo_bar.example.com.", 7, true, ""},
		{"https", "FOO-BAR.example.com", "foo-bar.example.com.", 443, true, ""},
		{"smtp", "✉️.example.com", "xn--4bi.example.com.", 25, true, ""},
	}

	for _, tt := range tests {
		testname := fmt.Sprintf("%v://%v", tt.scheme, tt.hostPort)
		t.Run(testname, func(t *testing.T) {
			r := require.New(t)

			hp, err := NewWithScheme(tt.hostPort, tt.scheme, tt.forceFQDN)
			r.Equal(tt.host, hp.Host)
			r.Equal(tt.port, hp.Port)

			if tt.err != "" {
				r.EqualError(err, tt.err)
			} else {
				r.NoError(err)
			}
		})
	}
}

package conntrack

import (
	"fmt"
	"io"
	"log"
	"net"
	"testing"
	"time"

	"github.com/sirupsen/logrus"
	"github.com/stretchr/testify/assert"
)

// TestInstrumentedConnByteCounting sends a fixed size message between two
// instrumented connections and ensures the bytes in and out are correct.
func TestInstrumentedConnByteCounting(t *testing.T) {
	assert := assert.New(t)

	addr := "localhost:0"
	ln, err := net.Listen("tcp", addr)
	if err != nil {
		t.Fatal(err)
	}
	defer ln.Close()

	tr := NewTestTracker(0)
	sent := []byte("X-Smokescreen-Test")

	writerErrChan := make(chan error, 1)
	go func() {
		defer close(writerErrChan)
		conn, err := ln.Accept()
		if err != nil {
			writerErrChan <- fmt.Errorf("error accepting: %w", err)
			return
		}

		icWriter := tr.NewInstrumentedConn(conn, logrus.NewEntry(testLogger), "test", "localhost", "http", "test_project")

		n, err := icWriter.Write(sent)
		if err != nil {
			writerErrChan <- fmt.Errorf("error writing: %w", err)
			return
		}
		conn.Close()

		if len(sent) != n {
			writerErrChan <- fmt.Errorf("length sent wasn't expected value: %d != %d", len(sent), n)
			return
		}
		bytesOut := *icWriter.BytesOut
		if uint64(len(sent)) != bytesOut {
			writerErrChan <- fmt.Errorf("bytes out value wasn't expected value: %d != %d", len(sent), bytesOut)
			return
		}
	}()

	conn, err := net.Dial("tcp", ln.Addr().String())
	if err != nil {
		t.Fatal(err)
	}
	icReader := tr.NewInstrumentedConn(conn, logrus.NewEntry(testLogger), "testBytesInOut", "localhost", "http", "test_project")

	readerErrChan := make(chan error, 1)
	go func() {
		defer close(readerErrChan)
		read := make([]byte, len(sent))
		for {
			_, err := icReader.Read(read)
			if err != nil {
				if err != io.EOF {
					readerErrChan <- err
				}
				return
			}
			assert.Equal(sent, read)
		}
	}()

	assert.NoError(<-writerErrChan)
	assert.NoError(<-readerErrChan)
	assert.Equal(uint64(len(sent)), *icReader.BytesIn)
}

func TestInstrumentedConnIdle(t *testing.T) {
	assert := assert.New(t)

	tr := NewTestTracker(time.Millisecond)
	ic := tr.NewInstrumentedConn(&net.UnixConn{}, logrus.NewEntry(testLogger), "testIdle", "localhost", "egress", "test_project")

	ic.Write([]byte("egress"))
	assert.False(ic.Idle())

	time.Sleep(time.Second)
	assert.True(ic.Idle())
}

var timeoutTests = []struct {
	name          string
	timeout       time.Duration
	expectedError bool
}{
	{"no timeout with zero duration", 0, false},
	{"timeout after duration", 50 * time.Millisecond, true},
}

func TestInstrumentedConnWithTimeout(t *testing.T) {
	addr := "localhost:0"
	ln, err := net.Listen("tcp", addr)
	if err != nil {
		t.Fatal(err)
	}
	defer ln.Close()

	handler := func(ln net.Listener, errCh chan error) {
		c, err := ln.Accept()
		errCh <- err
		time.Sleep(250 * time.Millisecond)
		c.Write([]byte("timeout-test"))
		defer c.Close()
	}

	tr := NewTestTracker(0)

	for _, tt := range timeoutTests {
		errCh := make(chan error)
		go handler(ln, errCh)

		c, err := net.Dial("tcp", ln.Addr().String())
		if err != nil {
			t.Fatal(err)
		}

		lnErr := <-errCh
		if lnErr != nil {
			t.Fatalf("failed to call Accept() on listener: %v", err)
		}

		var b [1]byte
		ic := tr.NewInstrumentedConnWithTimeout(c, tt.timeout, logrus.NewEntry(testLogger), "test", "testHost", "http", "test_project")

		_, err = ic.Read(b[:])
		if err == nil && tt.expectedError {
			t.Fatalf("%v: expected=%v got=%v", tt.name, tt.expectedError, err)
		}

		if err != nil && !tt.expectedError {
			t.Fatalf("%v: expected=%v got=%v", tt.name, tt.expectedError, err)
		}

		if err != nil {
			if err, ok := err.(net.Error); ok && !err.Timeout() {
				log.Fatal(err)
				t.Fatalf("%v: expected timeout error - got: %v", tt.name, err)
			}
		}
		ic.Close()
	}
}

package conntrack

import (
	"net"
	"sync/atomic"
	"testing"
	"time"

	"github.com/sirupsen/logrus"
	"github.com/stretchr/testify/assert"
	"github.com/stripe/smokescreen/pkg/smokescreen/metrics"
)

var testLogger = logrus.New()

// TestConnTrackerDelete is a sanity check to ensure we aren't leaking
// connection references in the tracker's sync.Map
func TestConnTrackerDelete(t *testing.T) {
	tr := NewTestTracker(time.Second * 1)

	ic := tr.NewInstrumentedConn(&net.UnixConn{}, logrus.NewEntry(testLogger), "testDeleteConn", "localhost", "http", "test_project")
	ic.Close()

	tr.Range(func(k, v interface{}) bool {
		t.Fatal("conn map should be empty")
		return false
	})
}

// TestConnTrackerMaybeIdleIn tests that our `IdleIn` calculations are correct
func TestConnTrackerMaybeIdleIn(t *testing.T) {
	assert := assert.New(t)

	tr := NewTestTracker(time.Nanosecond)
	ic := tr.NewInstrumentedConn(&net.UnixConn{}, logrus.NewEntry(testLogger), "testMaybeIdle", "localhost", "http", "test_project")

	time.Sleep(time.Millisecond)

	// All connections should be idle
	assert.Zero(tr.MaybeIdleIn(time.Nanosecond))

	ic.Write([]byte("egress"))

	idleIn := tr.MaybeIdleIn(time.Second).Round(time.Second)
	assert.Equal(time.Second, idleIn)
}

func NewTestTracker(idle time.Duration) *Tracker {
	sd := atomic.Value{}
	sd.Store(false)

	return NewTracker(idle, metrics.NewNoOpMetricsClient(), logrus.New(), sd, nil)
}

// TestConnSuccessRateTracker tests that a ConnTracker with a ConnSuccessRateTracker correctly
// records connection attempts, calculates a success rate, and expires stored attempts.
func TestConnSuccessRateTracker(t *testing.T) {
	type record struct {
		host    string
		success bool
	}

	var testCases = []struct {
		name         string
		additions    []record
		waitTime     time.Duration
		expectedRate float64
		totalConns   int
	}{
		{"fifty-percent-success", []record{{"foo.com", true}, {"bar.com", false}}, 1 * time.Second, 50.0, 2},
		{"no-records", []record{}, 2 * time.Second, 100.0, 0},
		// If we wait beyond the calculation window, we should have no records and return the default 100% rate
		{"expire-records", []record{{"foo.com", true}, {"bar.com", false}}, 3 * time.Second, 100.0, 0},
		// Only the most recent record for a host is used in the computation
		{"dedup-hosts", []record{{"foo.com", false}, {"bar.com", false}, {"foo.com", true}}, 1 * time.Second, 50.0, 2},
		// Our normalization scheme should resolve all of these to "foo.com"
		{"hostnames-normalized", []record{{"one.foo.com:443", false}, {"two.foo.com:80", false}, {"three.bar.foo.com", true}}, 1 * time.Second, 100.0, 1},
	}

	for _, tc := range testCases {
		t.Run(tc.name, func(t *testing.T) {
			assert := assert.New(t)

			sd := atomic.Value{}
			sd.Store(false)
			mockMetricsClient := metrics.NewMockMetricsClient()
			tracker := NewTracker(
				time.Second,
				metrics.NewNoOpMetricsClient(), // We aren't testing metrics for the Tracker here, only for the embedded ConnSuccessRateTracker
				logrus.New(),
				sd,
				StartNewConnSuccessRateTracker(500*time.Millisecond, 2*time.Second, 10*time.Second, mockMetricsClient))

			for _, record := range tc.additions {
				tracker.RecordAttempt(record.host, record.success)
			}

			time.Sleep(tc.waitTime)

			stats := tracker.ReportConnectionSuccessRate()
			assert.InDelta(tc.expectedRate, stats.ConnSuccessRate, 0.01)
			assert.Equal(tc.totalConns, stats.TotalConns)

			v, err := mockMetricsClient.GetValues("cn.atpt.distinct_domains_success_rate", map[string]string{})
			assert.NoError(err)
			assert.Equal(tc.expectedRate, v[len(v)-1])

			v, err = mockMetricsClient.GetValues("cn.atpt.distinct_domains", map[string]string{})
			assert.NoError(err)
			assert.Equal(tc.totalConns, int(v[len(v)-1]))

		})
	}
}

func TestNoConnSuccessRateTracker(t *testing.T) {
	assert := assert.New(t)
	tracker := NewTestTracker(time.Second)

	assert.NotPanics(func() { tracker.RecordAttempt("foo.com", true) })
	stats := tracker.ReportConnectionSuccessRate()
	assert.Nil(stats)

}

func TestNormalizeDomainName(t *testing.T) {

	var testCases = []struct {
		domain     string
		normalized string
	}{
		{"34wfasdaskjgsf.hosting.company.com:443", "company.com"},
		{"foo.com", "foo.com"},
		{"bbc.co.uk:12345", "bbc.co.uk"},
		{"ab.cd.ef.co:000", "ef.co"},
		{"172.168.0.1:555", "172.168.0.1"},
		{"[2001:db8::1]:80", "2001:db8::1"},
	}

	for _, tc := range testCases {
